import { GoogleGenAI } from "@google/genai";

export async function POST(request: Request) {
    try {
        const { message, context } = await request.json();

        // 1. Security Check: Ensure server key exists
        if (!process.env.API_KEY) {
             return new Response(JSON.stringify({ error: "Server configuration error: Demo key not found." }), { status: 500 });
        }

        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

        // 2. Define System Prompt on Server (Prevent Prompt Injection/Misuse of key)
        const systemPrompt = `You are MonkeySmile 🐵, a sassy, fun, and brutally honest financial buddy.
        You have access to the user's current financial snapshot below.

        FINANCIAL DATA CONTEXT:
        ${context}

        INSTRUCTIONS:
        1. Be concise and conversational.
        2. Use emojis (especially 🐵, 🍌, 💸).
        3. Use the provided financial context to answer accurately.
        4. If the user asks "Can I afford X?", check their 'Net' or 'Nice-to-Have' spending.
        5. If 'Waste' spending is high, gently roast them.
        6. If they are doing well (high savings, positive net), cheer them on!
        7. Never make up numbers. If the data isn't in the context, say "I don't see that in your records."`;

        // 3. Call Gemini
        const response = await ai.models.generateContent({
            model: "gemini-2.5-flash", // Use a cost-effective model for the free demo
            contents: [
                { role: 'user', parts: [{ text: systemPrompt + "\n\nUser Question: " + message }] }
            ]
        });

        return new Response(JSON.stringify({ response: response.text }), { 
            headers: { 'Content-Type': 'application/json' } 
        });

    } catch (error: any) {
        console.error("Chat API Error:", error);
        return new Response(JSON.stringify({ error: "Demo AI is currently unavailable." }), { status: 500 });
    }
}

import { Transaction, AIMode, TransactionCategory, AppSettings } from '../types';
import { useSettingsStore, getDecryptedApiKey } from '../stores/useSettingsStore';
import { GoogleGenAI, Type } from "@google/genai";
import { CATEGORY_HIERARCHY } from '../constants';

interface CategorizationResult {
  id: string;
  category: TransactionCategory;
  subCategory?: string;
  confidence: number;
  reason: string;
}

// --- Connection Testing ---

export const testAiConnection = async (): Promise<boolean> => {
    const settings = useSettingsStore.getState();
    const mode = settings.aiMode;

    if (mode === 'cloud') {
        const apiKey = getDecryptedApiKey(settings);
        // If no key, we test the server endpoint availability
        if (!apiKey) {
            try {
                const response = await fetch('/api/chat', {
                     method: 'POST',
                     headers: { 'Content-Type': 'application/json' },
                     body: JSON.stringify({ message: "ping", context: "ping" })
                });
                if (!response.ok) throw new Error("Server demo unavailable");
                return true;
            } catch (e) {
                throw new Error("No API Key set and Demo Server unreachable.");
            }
        }

        try {
            const ai = new GoogleGenAI({ apiKey });
            const response = await ai.models.generateContent({
                model: settings.geminiConfig.model,
                contents: "Hello, reply with 'OK'.",
            });
            return !!response.text;
        } catch (e: any) {
            throw new Error(`Gemini Error: ${e.message}`);
        }
    } else if (mode === 'groq') {
        const apiKey = getDecryptedApiKey(settings);
        if (!apiKey) throw new Error("Missing Groq API Key");

        try {
            const response = await fetch('https://api.groq.com/openai/v1/chat/completions', {
                method: 'POST',
                headers: {
                    'Authorization': `Bearer ${apiKey}`,
                    'Content-Type': 'application/json'
                },
                body: JSON.stringify({
                    model: settings.groqConfig.model,
                    messages: [{ role: 'user', content: "Reply with JSON: { \"status\": \"OK\" }" }],
                    response_format: { type: "json_object" }
                })
            });

            if (!response.ok) {
                const err = await response.json();
                throw new Error(err.error?.message || 'Groq connection failed');
            }
            return true;
        } catch (e: any) {
            throw new Error(`Groq Error: ${e.message}`);
        }
    } else {
        const { baseUrl, port, model } = settings.ollamaConfig;
        // Ensure protocol is present
        const safeBaseUrl = baseUrl.startsWith('http') ? baseUrl : `http://${baseUrl}`;
        const url = `${safeBaseUrl}:${port}/api/generate`;

        try {
            const response = await fetch(url, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    model: model,
                    prompt: "Reply with OK",
                    stream: false
                })
            });
            if (!response.ok) throw new Error("Ollama connection refused");
            return true;
        } catch (e: any) {
            // Specific handling for CORS/Network errors typical with local LLMs in browser
            if (e.message === 'Failed to fetch' || e.name === 'TypeError') {
                 throw new Error(
                    "Connection Failed. \n\n" +
                    "1. QUIT the Ollama app from your taskbar/menu bar.\n" +
                    "2. Run this command in your terminal:\n\n" +
                    "   Mac/Linux:\n   OLLAMA_ORIGINS=\"*\" ollama serve\n\n" +
                    "   Windows (PowerShell):\n   $env:OLLAMA_ORIGINS=\"*\"; ollama serve"
                 );
            }
            throw new Error(`Local AI Error: ${e.message}. Is Ollama running?`);
        }
    }
};

// --- Chat Service (MonkeySmile) ---

export const chatWithFinancialAgent = async (
    userQuery: string,
    financialContext: string
): Promise<string> => {
    const settings = useSettingsStore.getState();
    const apiKey = getDecryptedApiKey(settings);

    // System prompt defines the persona
    const systemPrompt = `You are MonkeySmile 🐵, a sassy, fun, and brutally honest financial buddy.
    You have access to the user's current financial snapshot below.

    FINANCIAL DATA CONTEXT:
    ${financialContext}

    INSTRUCTIONS:
    1. Be concise and conversational.
    2. Use emojis (especially 🐵, 🍌, 💸).
    3. Use the provided financial context to answer accurately.
    4. If the user asks "Can I afford X?", check their 'Net' or 'Nice-to-Have' spending.
    5. If 'Waste' spending is high, gently roast them.
    6. If they are doing well (high savings, positive net), cheer them on!
    7. Never make up numbers. If the data isn't in the context, say "I don't see that in your records."`;

    if (settings.aiMode === 'cloud') {
         // Fallback to Server Proxy if no local key provided
         if (!apiKey) {
            try {
                const response = await fetch('/api/chat', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({
                        message: userQuery,
                        context: financialContext
                    })
                });

                if (!response.ok) {
                    const err = await response.json();
                    throw new Error(err.error || "Demo server error");
                }

                const data = await response.json();
                return data.response;
            } catch (e: any) {
                throw new Error(e.message || "Failed to connect to demo server");
            }
         }

         const ai = new GoogleGenAI({ apiKey });
         const response = await ai.models.generateContent({
             model: settings.geminiConfig.model,
             contents: [
                 { role: 'user', parts: [{ text: systemPrompt + "\n\nUser Question: " + userQuery }] }
             ]
         });
         return response.text || "I'm speechless 🐵 (No response from AI)";
    } else if (settings.aiMode === 'groq') {
         if (!apiKey) throw new Error("Missing API Key");
         const response = await fetch('https://api.groq.com/openai/v1/chat/completions', {
            method: 'POST',
            headers: {
                'Authorization': `Bearer ${apiKey}`,
                'Content-Type': 'application/json'
            },
            body: JSON.stringify({
                model: settings.groqConfig.model,
                messages: [
                    { role: 'system', content: systemPrompt },
                    { role: 'user', content: userQuery }
                ]
            })
        });

        if (!response.ok) {
            const err = await response.json();
            throw new Error(err.error?.message || "Groq API Error");
        }

        const data = await response.json();
        return data.choices?.[0]?.message?.content || "Groq is silent 🐵";
    } else {
        // Ollama
        const { baseUrl, port, model } = settings.ollamaConfig;
        const safeBaseUrl = baseUrl.startsWith('http') ? baseUrl : `http://${baseUrl}`;
        const url = `${safeBaseUrl}:${port}/api/generate`;

        const response = await fetch(url, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                model: model,
                prompt: `${systemPrompt}\n\nUser Question: ${userQuery}`,
                stream: false
            })
        });

        if (!response.ok) throw new Error("Ollama connection failed");

        const data = await response.json();
        return data.response || "Thinking... 🐵";
    }
};

// --- Main Categorization Service ---

export const categorizeWithAI = async (
  transactions: Transaction[],
  mode: AIMode,
  onChunkProcessed?: (results: CategorizationResult[]) => void
): Promise<void> => {
  const settings = useSettingsStore.getState();

  // Demo Mode Interception
  if (settings.isDemoMode) {
      await simulateCategorization(transactions, onChunkProcessed);
      return;
  }

  // We process whatever is passed in. The caller is responsible for filtering (e.g. only Uncategorized, or Unapproved).
  const toProcess = transactions;
  if (toProcess.length === 0) return;

  if (mode === 'cloud') {
    await categorizeWithGemini(toProcess, onChunkProcessed);
  } else if (mode === 'groq') {
    await categorizeWithGroq(toProcess, onChunkProcessed);
  } else {
    await categorizeWithOllama(toProcess, onChunkProcessed);
  }
};

const categorizeWithGemini = async (
    transactions: Transaction[],
    onChunkProcessed?: (results: CategorizationResult[]) => void
): Promise<void> => {
    const settings = useSettingsStore.getState();
    const apiKey = getDecryptedApiKey(settings);
    const model = settings.geminiConfig.model;

    if (!apiKey) {
        console.warn("No API key provided, using simulation.");
        await simulateCategorization(transactions, onChunkProcessed);
        return;
    }

    const ai = new GoogleGenAI({ apiKey });

    // OPTIMIZATION: High batch size, low frequency.
    const BATCH_SIZE = 25; 

    for (let i = 0; i < transactions.length; i += BATCH_SIZE) {
        const batch = transactions.slice(i, i + BATCH_SIZE);

        const prompt = `
            You are a financial analyst. Categorize these transactions based on the provided hierarchy.

            Hierarchy:
            ${JSON.stringify(CATEGORY_HIERARCHY)}

            Transactions:
            ${JSON.stringify(batch.map(t => ({ id: t.id, desc: t.description, amt: t.amount, cat: t.originalCategory })))}

            Instructions:
            1. Select the most appropriate Category and Subcategory from the hierarchy.
            2. Use the 'cat' field (original bank category) as a hint if available.
            3. Return a valid JSON array matching the schema.
        `;

        try {
            const response = await ai.models.generateContent({
                model: model,
                contents: prompt,
                config: { 
                    responseMimeType: "application/json",
                    responseSchema: {
                        type: Type.ARRAY,
                        items: {
                            type: Type.OBJECT,
                            properties: {
                                id: { type: Type.STRING },
                                category: { type: Type.STRING },
                                subCategory: { type: Type.STRING },
                                confidence: { type: Type.NUMBER },
                                reason: { type: Type.STRING }
                            },
                            required: ["id", "category", "confidence", "reason"]
                        }
                    }
                }
            });

            const text = response.text;
            if (text) {
                const results: CategorizationResult[] = JSON.parse(text);
                if (onChunkProcessed) onChunkProcessed(results);
            }
        } catch (e: any) {
            console.error("Gemini Batch Failed", e);
            if (e.status === 429 || e.message?.includes('429')) {
                throw new Error("Gemini Rate Limit Exceeded (429). Please try again in 1 minute.");
            }

            // Fallback for failed batch so the UI knows they failed
            const fallbackResults = batch.map(t => ({
                id: t.id,
                category: TransactionCategory.Uncategorized,
                confidence: 0,
                reason: "AI Request Failed: " + (e.message || "Unknown error")
            }));
            if (onChunkProcessed) onChunkProcessed(fallbackResults);
        }

        await new Promise(r => setTimeout(r, 4000));
    }
};

const categorizeWithGroq = async (
    transactions: Transaction[],
    onChunkProcessed?: (results: CategorizationResult[]) => void
): Promise<void> => {
    const settings = useSettingsStore.getState();
    const apiKey = getDecryptedApiKey(settings);
    const model = settings.groqConfig.model;
    const hierarchyStr = JSON.stringify(CATEGORY_HIERARCHY);

    // Groq creates fast inference, but we still batch to reduce network round trips and stay within TPM/RPM.
    const BATCH_SIZE = 10; 

    for (let i = 0; i < transactions.length; i += BATCH_SIZE) {
        const batch = transactions.slice(i, i + BATCH_SIZE);
        const batchStr = JSON.stringify(batch.map(t => ({ 
            id: t.id, 
            desc: t.description, 
            amt: t.amount, 
            original: t.originalCategory 
        })));

        // Strictly enforce JSON structure in the prompt to avoid "Failed to generate JSON" errors from Groq
        const systemPrompt = `
        You are a strict JSON API for financial categorization.

        Hierarchy: ${hierarchyStr}

        Output **only** valid JSON.
        The JSON must be an object with a single key "results" containing an array.
        Each item in the array must match this schema:
        {
            "id": "string (original id)",
            "category": "string (from hierarchy keys)",
            "subCategory": "string (from hierarchy values)",
            "confidence": number (0.0 to 1.0),
            "reason": "string (short explanation)"
        }

        Do not add any markdown formatting (like \`\`\`json). Do not add explanations outside the JSON.
        `;

        try {
            const response = await fetch('https://api.groq.com/openai/v1/chat/completions', {
                method: 'POST',
                headers: {
                    'Authorization': `Bearer ${apiKey}`,
                    'Content-Type': 'application/json'
                },
                body: JSON.stringify({
                    model: model,
                    messages: [
                        { role: "system", content: systemPrompt },
                        { role: "user", content: `Categorize these transactions. Return valid JSON only. Transactions: ${batchStr}` }
                    ],
                    response_format: { type: "json_object" },
                    temperature: 0 // Deterministic output helps with strict JSON
                })
            });

            if (!response.ok) {
                if (response.status === 429) {
                     throw new Error("Groq Rate Limit Exceeded. Please check your plan.");
                }
                const err = await response.json();
                throw new Error(err.error?.message || "Groq API Error");
            }

            const data = await response.json();
            const content = data.choices[0]?.message?.content;

            if (content) {
                let parsed;
                try {
                    parsed = JSON.parse(content);

                    // Handle wrapping logic
                    if (parsed.results && Array.isArray(parsed.results)) {
                        parsed = parsed.results;
                    } else if (!Array.isArray(parsed)) {
                        // Attempt to find the first array value in the object
                        const values = Object.values(parsed);
                        const arrayValue = values.find(v => Array.isArray(v));
                        if (arrayValue) {
                            parsed = arrayValue;
                        }
                    }
                } catch (e) {
                    console.error("Failed to parse Groq JSON", content);
                }

                if (Array.isArray(parsed)) {
                    // Normalize fields
                    const results: CategorizationResult[] = parsed.map((item: any) => ({
                        id: item.id,
                        category: item.category || TransactionCategory.Uncategorized,
                        subCategory: item.subCategory,
                        confidence: item.confidence || 0.8,
                        reason: item.reason || "Groq AI"
                    }));
                    if (onChunkProcessed) onChunkProcessed(results);
                }
            }

        } catch (e: any) {
            console.error("Groq Batch Failed", e);
             // Propagate rate limits or specific errors
            if (e.message.includes("Rate Limit") || e.message.includes("JSON")) {
                 throw e;
            }

            // Fallback for failed batch
            const fallbackResults = batch.map(t => ({
                id: t.id,
                category: TransactionCategory.Uncategorized,
                confidence: 0,
                reason: "AI Request Failed: " + (e.message || "Unknown error")
            }));
            if (onChunkProcessed) onChunkProcessed(fallbackResults);
        }

        // Rate limit buffer
        await new Promise(r => setTimeout(r, 2000));
    }
};

const categorizeWithOllama = async (
    transactions: Transaction[],
    onChunkProcessed?: (results: CategorizationResult[]) => void
): Promise<void> => {
    const settings = useSettingsStore.getState();
    const { baseUrl, port, model } = settings.ollamaConfig;
    // Ensure protocol is present
    const safeBaseUrl = baseUrl.startsWith('http') ? baseUrl : `http://${baseUrl}`;
    const url = `${safeBaseUrl}:${port}/api/generate`;

    const hierarchyStr = JSON.stringify(CATEGORY_HIERARCHY);

    const promptBase = `You are a financial assistant. Categorize the transaction into a Category and a Subcategory from this hierarchy: 
    ${hierarchyStr}.

    Instructions:
    1. Pick the best Main Category.
    2. Pick the best Subcategory from that Main Category.
    3. Return ONLY JSON: { "category": "...", "subCategory": "...", "confidence": 0.9, "reason": "..." }.

    Transaction: `;

    // Process one by one or small batches for local AI
    for (const tx of transactions) {
        try {
            const response = await fetch(url, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    model: model,
                    prompt: `${promptBase} Description: ${tx.description}, Amount: ${tx.amount}, Original Category: ${tx.originalCategory || 'N/A'}`,
                    stream: false,
                    format: "json"
                })
            });

            if(!response.ok) throw new Error("Ollama connection failed");

            const data = await response.json();
            let result;

            // Handle cases where Ollama doesn't enforce JSON mode perfectly
            try {
                result = JSON.parse(data.response);
            } catch (parseError) {
                 // Fallback simple parsing if model chats instead of JSON
                 console.warn("Failed to parse JSON from Ollama", data.response);
                 // Don't throw here, just treat as failed tx
                 throw new Error("Invalid JSON response");
            }

            const processedResult: CategorizationResult = {
                id: tx.id,
                category: result.category || TransactionCategory.Uncategorized,
                subCategory: result.subCategory,
                confidence: result.confidence || 0.5,
                reason: result.reason || "Local AI"
            };

            if (onChunkProcessed) onChunkProcessed([processedResult]);

        } catch (e: any) {
             if (e.message === 'Failed to fetch') {
                 throw new Error("CORS Error. Run: $env:OLLAMA_ORIGINS=\"*\"; ollama serve (Windows) OR OLLAMA_ORIGINS=\"*\" ollama serve (Mac/Linux)");
            }

            // Mark individual failure
            const failedResult: CategorizationResult = {
                id: tx.id,
                category: TransactionCategory.Uncategorized,
                confidence: 0,
                reason: "AI Error: " + (e.message || "Unknown")
            };
            if (onChunkProcessed) onChunkProcessed([failedResult]);
        }
    }
};

// Simulation for preview environments without backend/key
const simulateCategorization = async (
    transactions: Transaction[],
    onChunkProcessed?: (results: CategorizationResult[]) => void
): Promise<void> => {
    const BATCH_SIZE = 5;

    for (let i = 0; i < transactions.length; i += BATCH_SIZE) {
        const batch = transactions.slice(i, i + BATCH_SIZE);

        await new Promise(resolve => setTimeout(resolve, 800)); // Fake network delay

        const results = batch.map(t => {
            const desc = t.description.toLowerCase();
            const origCat = (t.originalCategory || '').toLowerCase();

            let cat = TransactionCategory.Uncategorized;
            let subCat = undefined;
            let reason = "Unsure";

            // Matching Demo Data Original Categories
            if (origCat === 'rent') { cat = TransactionCategory.MustHave; subCat = 'Housing'; reason = "Rent"; }
            else if (origCat === 'bills') { cat = TransactionCategory.MustHave; subCat = 'Utilities'; reason = "Utility Bill"; }
            else if (origCat === 'insurance') { cat = TransactionCategory.MustHave; subCat = 'Insurance'; reason = "Policy"; }
            else if (origCat === 'utilities') { cat = TransactionCategory.MustHave; subCat = 'Utilities'; reason = "City/Power"; }
            else if (origCat === 'subscription') { cat = TransactionCategory.NiceToHave; subCat = 'Entertainment'; reason = "Sub"; }
            else if (origCat === 'shopping') { cat = TransactionCategory.NiceToHave; subCat = 'Shopping'; reason = "Retail"; }
            else if (origCat === 'groceries') { cat = TransactionCategory.MustHave; subCat = 'Food & Groceries'; reason = "Grocery Store"; }
            else if (origCat === 'gas') { cat = TransactionCategory.MustHave; subCat = 'Transportation'; reason = "Fuel"; }
            else if (origCat === 'travel') { cat = TransactionCategory.NiceToHave; subCat = 'Travel & Leisure'; reason = "Trip"; }
            else if (origCat === 'dining') { cat = TransactionCategory.NiceToHave; subCat = 'Dining Out'; reason = "Restaurant"; }
            else if (origCat === 'income') { cat = TransactionCategory.Income; subCat = 'Salary'; reason = "Payroll"; }
            // General fallbacks based on description keywords
            else if (origCat.includes('income') || origCat.includes('deposit')) {
                 cat = TransactionCategory.Income;
                 subCat = 'Other Income';
                 reason = "Based on bank category";
            }
            else if (t.amount > 0 && !desc.includes('refund')) {
                cat = TransactionCategory.Income;
                subCat = desc.includes('salary') ? 'Salary' : 'Other Income';
                reason = "Positive amount";
            } else if (desc.includes('payment') || desc.includes('transfer')) {
                cat = TransactionCategory.InternalTransfer;
                subCat = 'Credit Card Payment';
                reason = "Transfer detected";
            } else if (desc.includes('starbucks') || desc.includes('coffee')) {
                cat = TransactionCategory.NiceToHave;
                subCat = 'Dining Out';
                reason = "Coffee";
            } else if (desc.includes('netflix') || desc.includes('spotify')) {
                cat = TransactionCategory.NiceToHave;
                subCat = 'Entertainment';
                reason = "Subscription";
            } else if (desc.includes('fee')) {
                cat = TransactionCategory.Waste;
                subCat = 'Late Fees & Penalties';
                reason = "Fee detected";
            } else if (desc.includes('savings')) {
                cat = TransactionCategory.Save;
                subCat = 'General Savings';
                reason = "Saving";
            } else {
                cat = TransactionCategory.NiceToHave;
                subCat = 'Shopping';
            }

            return {
                id: t.id,
                category: cat,
                subCategory: subCat,
                confidence: 0.85,
                reason
            };
        });

        if (onChunkProcessed) onChunkProcessed(results);
    }
};

import React, { useState, useRef, useEffect } from 'react';
import { useTransactionStore } from '../stores/useTransactionStore';
import { useSettingsStore } from '../stores/useSettingsStore';
import { chatWithFinancialAgent } from '../services/aiService';
import { Transaction, TransactionCategory } from '../types';
import { MessageCircle, Send, X, Smile, Settings, Loader2 } from 'lucide-react';
import { Button, Input, Card, CardHeader, CardContent } from './UI';
import { cn, formatCurrency } from '../lib/utils';

interface Message {
    id: string;
    role: 'user' | 'assistant';
    content: string;
    timestamp: number;
}

interface MonkeySmileChatProps {
    onNavigate?: (view: 'settings' | 'dashboard' | 'upload') => void;
}

export const MonkeySmileChat: React.FC<MonkeySmileChatProps> = ({ onNavigate }) => {
    const { transactions } = useTransactionStore();
    // Subscribe to config objects so component re-renders when keys are updated
    const { isDemoMode, aiMode, geminiConfig, groqConfig } = useSettingsStore();
    const [isOpen, setIsOpen] = useState(false);
    const [messages, setMessages] = useState<Message[]>([
        { 
            id: 'intro', 
            role: 'assistant', 
            content: "Hey! I'm MonkeySmile 🐵. Ask me anything about your budget. Try 'Can I afford pizza?' or 'Roast my spending'.", 
            timestamp: Date.now() 
        }
    ]);
    const [inputValue, setInputValue] = useState('');
    const [isLoading, setIsLoading] = useState(false);
    const messagesEndRef = useRef<HTMLDivElement>(null);

    // Scroll to bottom
    useEffect(() => {
        if (messagesEndRef.current) {
            messagesEndRef.current.scrollIntoView({ behavior: 'smooth' });
        }
    }, [messages, isOpen]);

    const isAIReady = React.useMemo(() => {
        if (aiMode === 'local') return true;

        // If Cloud mode, we allow fallback to server proxy if no key is present
        if (aiMode === 'cloud') {
            return true; 
        }

        if (aiMode === 'groq') {
            return !!groqConfig.apiKey && groqConfig.apiKey.length > 0;
        }

        return false;
    }, [aiMode, geminiConfig.apiKey, groqConfig.apiKey]);

    const buildFinancialContext = (txs: Transaction[]) => {
        const now = new Date();
        const currentMonthPrefix = now.toISOString().slice(0, 7); // YYYY-MM
        const monthlyTx = txs.filter(t => t.date.startsWith(currentMonthPrefix));

        const income = monthlyTx.filter(t => t.amount > 0).reduce((sum, t) => sum + t.amount, 0);
        const expenses = monthlyTx.filter(t => t.amount < 0).reduce((sum, t) => sum + Math.abs(t.amount), 0);
        const niceToHave = monthlyTx.filter(t => t.category === TransactionCategory.NiceToHave).reduce((sum, t) => sum + Math.abs(t.amount), 0);
        const waste = monthlyTx.filter(t => t.category === TransactionCategory.Waste).reduce((sum, t) => sum + Math.abs(t.amount), 0);

        // Group expenses by category
        const byCat: Record<string, number> = {};
        monthlyTx.filter(t => t.amount < 0).forEach(t => {
            byCat[t.category] = (byCat[t.category] || 0) + Math.abs(t.amount);
        });

        const topCategories = Object.entries(byCat)
            .sort(([,a], [,b]) => b - a)
            .slice(0, 3)
            .map(([cat, amt]) => `${cat}: ${formatCurrency(amt)}`)
            .join(', ');

        return `
        Month: ${currentMonthPrefix}
        Total Income: ${formatCurrency(income)}
        Total Expenses: ${formatCurrency(expenses)}
        Net Balance (Income - Expenses): ${formatCurrency(income - expenses)}
        Nice-to-Have Spend: ${formatCurrency(niceToHave)}
        Waste Spend: ${formatCurrency(waste)}
        Top Spending Categories: ${topCategories}
        Total Transactions: ${monthlyTx.length}
        Recent Transactions: ${monthlyTx.slice(0, 5).map(t => `${t.description} (${formatCurrency(t.amount)})`).join(', ')}
        `;
    };

    const handleSend = async (e?: React.FormEvent) => {
        e?.preventDefault();
        if (!inputValue.trim()) return;

        const userMsg: Message = {
            id: Date.now().toString(),
            role: 'user',
            content: inputValue.trim(),
            timestamp: Date.now()
        };

        setMessages(prev => [...prev, userMsg]);
        setInputValue('');
        setIsLoading(true);

        try {
            if (!isAIReady) {
                // Simulate delay then show error
                setTimeout(() => {
                    const errorMsg: Message = {
                        id: (Date.now() + 1).toString(),
                        role: 'assistant',
                        content: "I'd love to chat, but I need a brain! 🧠\n\nPlease go to Settings to configure your AI model.",
                        timestamp: Date.now()
                    };
                    setMessages(prev => [...prev, errorMsg]);
                    setIsLoading(false);
                }, 600);
                return;
            }

            const context = buildFinancialContext(transactions);
            const responseText = await chatWithFinancialAgent(userMsg.content, context);

            const botMsg: Message = {
                id: (Date.now() + 1).toString(),
                role: 'assistant',
                content: responseText,
                timestamp: Date.now()
            };
            setMessages(prev => [...prev, botMsg]);
        } catch (error: any) {
            const errorMsg: Message = {
                id: (Date.now() + 1).toString(),
                role: 'assistant',
                content: `Oops! Something went wrong: ${error.message}`,
                timestamp: Date.now()
            };
            setMessages(prev => [...prev, errorMsg]);
        } finally {
            setIsLoading(false);
        }
    };

    if (transactions.length === 0) return null;

    return (
        <>
            {/* Toggle Button */}
            <button
                onClick={() => setIsOpen(!isOpen)}
                className={cn(
                    "fixed bottom-6 right-6 z-40 p-4 rounded-full shadow-xl transition-all duration-300 hover:scale-105",
                    isOpen ? "bg-red-500 text-white rotate-90" : "bg-gradient-to-tr from-accent to-emerald-600 text-white"
                )}
                aria-label="Toggle MonkeySmile Chat"
            >
                {isOpen ? <X className="w-6 h-6" /> : <Smile className="w-6 h-6" />}
            </button>

            {/* Chat Window */}
            {isOpen && (
                <div className="fixed bottom-24 right-6 z-40 w-80 sm:w-96 flex flex-col animate-in slide-in-from-bottom-10 fade-in duration-300 origin-bottom-right">
                    <Card className="shadow-2xl border-0 overflow-hidden flex flex-col h-[500px]">
                        {/* Header */}
                        <div className="bg-gradient-to-r from-accent to-emerald-600 p-4 flex justify-between items-center text-white shrink-0">
                            <div className="flex items-center gap-2">
                                <div className="bg-white/20 p-1.5 rounded-full backdrop-blur-sm">
                                    <Smile className="w-5 h-5" />
                                </div>
                                <div>
                                    <h3 className="font-bold text-sm">MonkeySmile 🐵</h3>
                                    <p className="text-[10px] text-white/80 font-medium">Your Sassy Budget Buddy</p>
                                </div>
                            </div>
                            {/* If we have demo data AND no AI key, show DEMO. If we have AI key, we are 'Live' even with demo data. */}
                            {!isAIReady && isDemoMode && (
                                <div className="bg-white/20 px-2 py-0.5 rounded text-[10px] font-bold border border-white/10">
                                    DEMO
                                </div>
                            )}
                        </div>

                        {/* Messages */}
                        <div className="flex-1 overflow-y-auto p-4 space-y-4 bg-gray-50/50">
                            {messages.map((msg) => (
                                <div
                                    key={msg.id}
                                    className={cn(
                                        "flex w-full",
                                        msg.role === 'user' ? "justify-end" : "justify-start"
                                    )}
                                >
                                    <div
                                        className={cn(
                                            "max-w-[80%] rounded-2xl px-4 py-2.5 text-sm shadow-sm whitespace-pre-wrap",
                                            msg.role === 'user' 
                                                ? "bg-accent text-white rounded-br-none" 
                                                : "bg-white text-gray-800 border border-gray-100 rounded-bl-none"
                                        )}
                                    >
                                        {msg.content}
                                    </div>
                                </div>
                            ))}
                            {isLoading && (
                                <div className="flex justify-start w-full">
                                    <div className="bg-white border border-gray-100 px-4 py-3 rounded-2xl rounded-bl-none shadow-sm flex items-center gap-2">
                                        <div className="w-2 h-2 bg-gray-400 rounded-full animate-bounce [animation-delay:-0.3s]"></div>
                                        <div className="w-2 h-2 bg-gray-400 rounded-full animate-bounce [animation-delay:-0.15s]"></div>
                                        <div className="w-2 h-2 bg-gray-400 rounded-full animate-bounce"></div>
                                    </div>
                                </div>
                            )}
                            <div ref={messagesEndRef} />
                        </div>

                        {/* Footer / Input */}
                        <div className="p-3 bg-white border-t border-gray-100 shrink-0">
                            {!isAIReady ? (
                                <div className="text-center p-2 space-y-2">
                                    <p className="text-xs text-gray-500">
                                        Connect AI to chat with your data.
                                    </p>
                                    <Button size="sm" variant="outline" className="w-full text-xs" onClick={() => {
                                        if (onNavigate) {
                                            setIsOpen(false);
                                            onNavigate('settings');
                                        }
                                    }}>
                                        <Settings className="w-3 h-3 mr-1.5" />
                                        Configure in Settings
                                    </Button>
                                </div>
                            ) : null}

                            <form 
                                onSubmit={handleSend}
                                className={cn("flex items-center gap-2", !isAIReady && "opacity-50 pointer-events-none")}
                            >
                                <Input
                                    value={inputValue}
                                    onChange={(e) => setInputValue(e.target.value)}
                                    placeholder="Type a message..."
                                    className="flex-1 text-sm bg-gray-50 border-0 focus-visible:ring-1 focus-visible:ring-accent focus-visible:bg-white transition-all"
                                />
                                <Button 
                                    type="submit" 
                                    size="sm" 
                                    className="px-3 bg-accent hover:bg-accent-hover text-white shadow-sm"
                                    disabled={!inputValue.trim() || isLoading}
                                >
                                    <Send className="w-4 h-4" />
                                </Button>
                            </form>
                        </div>
                    </Card>
                </div>
            )}
        </>
    );
};

