        }
    ]);
    const [inputValue, setInputValue] = useState('');
    const [isLoading, setIsLoading] = useState(false);
    const messagesEndRef = useRef<HTMLDivElement>(null);

    // Scroll to bottom
    useEffect(() => {
        if (messagesEndRef.current) {
            messagesEndRef.current.scrollIntoView({ behavior: 'smooth' });
        }
    }, [messages, isOpen]);

    const isAIReady = React.useMemo(() => {
        if (aiMode === 'local') return true;

        // If Cloud mode, we allow fallback to server proxy if no key is present
        if (aiMode === 'cloud') {
            return true; 
        }

        if (aiMode === 'groq') {
            return !!groqConfig.apiKey && groqConfig.apiKey.length > 0;
        }

        return false;
    }, [aiMode, geminiConfig.apiKey, groqConfig.apiKey]);

    const buildFinancialContext = (txs: Transaction[]) => {
        if (txs.length === 0) return "No transaction data available.";

        // Find the latest date in the dataset to determine the "Current Month" context
        // This ensures that if the data is from 2023, we analyze 2023, not today's empty month.
        const sortedTxs = [...txs].sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
        const latestDate = sortedTxs[0].date; 
        const currentMonthPrefix = latestDate.slice(0, 7); // YYYY-MM

        const monthlyTx = txs.filter(t => t.date.startsWith(currentMonthPrefix));

        const income = monthlyTx.filter(t => t.amount > 0).reduce((sum, t) => sum + t.amount, 0);
        const expenses = monthlyTx.filter(t => t.amount < 0).reduce((sum, t) => sum + Math.abs(t.amount), 0);
        const niceToHave = monthlyTx.filter(t => t.category === TransactionCategory.NiceToHave).reduce((sum, t) => sum + Math.abs(t.amount), 0);
        const waste = monthlyTx.filter(t => t.category === TransactionCategory.Waste).reduce((sum, t) => sum + Math.abs(t.amount), 0);

        // Group expenses by category
        const byCat: Record<string, number> = {};
        monthlyTx.filter(t => t.amount < 0).forEach(t => {
            byCat[t.category] = (byCat[t.category] || 0) + Math.abs(t.amount);
        });

        const topCategories = Object.entries(byCat)
            .sort(([,a], [,b]) => b - a)
            .slice(0, 3)
            .map(([cat, amt]) => `${cat}: ${formatCurrency(amt)}`)
            .join(', ');

        // Calculate All-Time stats for broader context
        const allTimeIncome = txs.filter(t => t.amount > 0).reduce((sum, t) => sum + t.amount, 0);
        const allTimeExpenses = txs.filter(t => t.amount < 0).reduce((sum, t) => sum + Math.abs(t.amount), 0);
        const netWorthProxy = allTimeIncome - allTimeExpenses; // Crude approximation within dataset

        return `
        CONTEXT PERIOD: ${currentMonthPrefix} (Most recent data available)

        MONTHLY SNAPSHOT (${currentMonthPrefix}):
        - Total Income: ${formatCurrency(income)}
        - Total Expenses: ${formatCurrency(expenses)}
        - Net Balance: ${formatCurrency(income - expenses)}
        - 'Nice-to-Have' Spend: ${formatCurrency(niceToHave)}
        - 'Waste' Spend: ${formatCurrency(waste)}
        - Top Categories: ${topCategories}
        - Transaction Count: ${monthlyTx.length}

        RECENT TRANSACTIONS (Last 5): 
        ${monthlyTx.slice(0, 5).map(t => `- ${t.date}: ${t.description} (${formatCurrency(t.amount)}) [${t.category}]`).join('\n')}

        ALL-TIME DATA (${txs.length} txs total):
        - Total Inflow: ${formatCurrency(allTimeIncome)}
        - Total Outflow: ${formatCurrency(allTimeExpenses)}
        - Calculated Net (Inflow - Outflow): ${formatCurrency(netWorthProxy)}
        `;
    };

    const handleSend = async (e?: React.FormEvent) => {
        e?.preventDefault();
        if (!inputValue.trim()) return;

        const userMsg: Message = {
            id: Date.now().toString(),
            role: 'user',
            content: inputValue.trim(),
            timestamp: Date.now()
        };

        setMessages(prev => [...prev, userMsg]);
        setInputValue('');
        setIsLoading(true);

        try {
            if (!isAIReady) {
                // Simulate delay then show error
                setTimeout(() => {
                    const errorMsg: Message = {
                        id: (Date.now() + 1).toString(),
                        role: 'assistant',
                        content: "I'd love to chat, but I need a brain! 🧠\n\nPlease go to Settings to configure your AI model.",
                        timestamp: Date.now()
                    };
                    setMessages(prev => [...prev, errorMsg]);
                    setIsLoading(false);
                }, 600);
                return;
            }

            const context = buildFinancialContext(transactions);
            const responseText = await chatWithFinancialAgent(userMsg.content, context);

            const botMsg: Message = {
                id: (Date.now() + 1).toString(),
                role: 'assistant',
                content: responseText,
                timestamp: Date.now()
            };
            setMessages(prev => [...prev, botMsg]);
        } catch (error: any) {
            const errorMsg: Message = {
                id: (Date.now() + 1).toString(),
                role: 'assistant',
                content: `Oops! Something went wrong: ${error.message}`,
                timestamp: Date.now()
            };
            setMessages(prev => [...prev, errorMsg]);
        } finally {
            setIsLoading(false);
        }
    };

    if (transactions.length === 0) return null;

    return (
        <>
            {/* Toggle Button */}
            <button
                onClick={() => setIsOpen(!isOpen)}
                className={cn(
                    "fixed bottom-6 right-6 z-40 p-4 rounded-full shadow-xl transition-all duration-300 hover:scale-105",
                    isOpen ? "bg-red-500 text-white rotate-90" : "bg-gradient-to-tr from-accent to-emerald-600 text-white"
                )}
                aria-label="Toggle MonkeySmile Chat"
            >
                {isOpen ? <X className="w-6 h-6" /> : <Smile className="w-6 h-6" />}
            </button>

            {/* Chat Window */}
            {isOpen && (
                <div className="fixed bottom-24 right-6 z-40 w-80 sm:w-96 flex flex-col animate-in slide-in-from-bottom-10 fade-in duration-300 origin-bottom-right">
                    <Card className="shadow-2xl border-0 overflow-hidden flex flex-col h-[500px]">
                        {/* Header */}
                        <div className="bg-gradient-to-r from-accent to-emerald-600 p-4 flex justify-between items-center text-white shrink-0">
                            <div className="flex items-center gap-2">
                                <div className="bg-white/20 p-1.5 rounded-full backdrop-blur-sm">
                                    <Smile className="w-5 h-5" />
                                </div>
                                <div>
                                    <h3 className="font-bold text-sm">MonkeySmile 🐵</h3>
                                    <p className="text-[10px] text-white/80 font-medium">Your Sassy Budget Buddy</p>
                                </div>
                            </div>
                            {/* If we have demo data AND no AI key, show DEMO. If we have AI key, we are 'Live' even with demo data. */}
                            {!isAIReady && isDemoMode && (
                                <div className="bg-white/20 px-2 py-0.5 rounded text-[10px] font-bold border border-white/10">
                                    DEMO
                                </div>
                            )}
                        </div>

                        {/* Messages */}
                        <div className="flex-1 overflow-y-auto p-4 space-y-4 bg-gray-50/50">
                            {messages.map((msg) => (
                                <div
                                    key={msg.id}
                                    className={cn(
                                        "flex w-full",
                                        msg.role === 'user' ? "justify-end" : "justify-start"
                                    )}
                                >
                                    <div
                                        className={cn(
                                            "max-w-[80%] rounded-2xl px-4 py-2.5 text-sm shadow-sm whitespace-pre-wrap",
                                            msg.role === 'user' 
                                                ? "bg-accent text-white rounded-br-none" 
                                                : "bg-white text-gray-800 border border-gray-100 rounded-bl-none"
                                        )}
                                    >
                                        {msg.content}
                                    </div>
                                </div>
                            ))}
                            {isLoading && (
                                <div className="flex justify-start w-full">
                                    <div className="bg-white border border-gray-100 px-4 py-3 rounded-2xl rounded-bl-none shadow-sm flex items-center gap-2">
                                        <div className="w-2 h-2 bg-gray-400 rounded-full animate-bounce [animation-delay:-0.3s]"></div>
                                        <div className="w-2 h-2 bg-gray-400 rounded-full animate-bounce [animation-delay:-0.15s]"></div>
                                        <div className="w-2 h-2 bg-gray-400 rounded-full animate-bounce"></div>
                                    </div>
                                </div>
                            )}
                            <div ref={messagesEndRef} />
                        </div>

                        {/* Footer / Input */}
                        <div className="p-3 bg-white border-t border-gray-100 shrink-0">
                            {!isAIReady ? (
                                <div className="text-center p-2 space-y-2">
                                    <p className="text-xs text-gray-500">
                                        Connect AI to chat with your data.
                                    </p>
                                    <Button size="sm" variant="outline" className="w-full text-xs" onClick={() => {
                                        if (onNavigate) {
                                            setIsOpen(false);
                                            onNavigate('settings');
                                        }
                                    }}>
                                        <Settings className="w-3 h-3 mr-1.5" />
                                        Configure in Settings
                                    </Button>
                                </div>
                            ) : null}

                            <form 
                                onSubmit={handleSend}
                                className={cn("flex items-center gap-2", !isAIReady && "opacity-50 pointer-events-none")}
                            >
                                <Input
                                    value={inputValue}
                                    onChange={(e) => setInputValue(e.target.value)}
                                    placeholder="Type a message..."
                                    className="flex-1 text-sm bg-gray-50 border-0 focus-visible:ring-1 focus-visible:ring-accent focus-visible:bg-white transition-all"
                                />
                                <Button 
                                    type="submit" 
                                    size="sm" 
                                    className="px-3 bg-accent hover:bg-accent-hover text-white shadow-sm"
                                    disabled={!inputValue.trim() || isLoading}
                                >
                                    <Send className="w-4 h-4" />
                                </Button>
                            </form>
                        </div>
                    </Card>
                </div>
            )}
        </>
    );
};

import React, { useRef, useState, useEffect } from 'react';
import { Upload, FileText, AlertCircle, ArrowRight, Check, AlertTriangle, X, ArrowLeft, Trash2, PlusCircle, ChevronLeft, ChevronRight, RefreshCw, Copy, Database, Info, ExternalLink, Hash } from 'lucide-react';
import { Button, Card, CardContent, CardHeader, CardTitle, Input, Badge } from './UI';
import { getCSVHeaders, detectBankFormat, parseCSVWithMapping, getPreviewTransactions, autoDetectMapping } from '../lib/csvParser';
import { useTransactionStore } from '../stores/useTransactionStore';
import { useSettingsStore } from '../stores/useSettingsStore';
import { applyPatterns } from '../lib/localStorage';
import { cn, formatCurrency } from '../lib/utils';
import { MAX_FILE_SIZE_MB, SUPPORTED_BANKS } from '../constants';
import { CsvMapping, Transaction } from '../types';
import { v4 as uuidv4 } from 'uuid';

type UploaderState = 'idle' | 'mapping' | 'preview' | 'processing';
type PreviewTab = 'new' | 'duplicates';

// Extended type for internal use in this component
type DuplicateTransaction = Transaction & { duplicateReason: 'Already Imported' | 'Duplicate in File' };

interface DuplicateResolutionModalProps {
  transaction: DuplicateTransaction;
  allTransactions: Transaction[];
  onClose: () => void;
  onImport: () => void;
}

const DuplicateResolutionModal: React.FC<DuplicateResolutionModalProps> = ({ transaction, allTransactions, onClose, onImport }) => {
  // Find potential matches in existing data to show why it's a duplicate
  const exactMatches = allTransactions.filter(t => 
      t.date === transaction.date && 
      t.amount === transaction.amount && 
      t.description === transaction.description &&
      t.id !== transaction.id
  );

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-sm p-4">
      <Card className="w-full max-w-lg bg-white shadow-xl animate-in zoom-in-95 duration-200">
        <CardHeader className="border-b border-gray-100 pb-4">
          <div className="flex justify-between items-start">
             <CardTitle className="text-lg flex items-center gap-2 text-orange-600">
                <AlertTriangle className="w-5 h-5" />
                Duplicate Detected
             </CardTitle>
             <button onClick={onClose} className="text-gray-400 hover:text-gray-600">
                <X className="w-5 h-5" />
             </button>
          </div>
        </CardHeader>
        <CardContent className="pt-6 space-y-6">
            <div className="space-y-2">
                <p className="text-sm text-gray-500">
                    This transaction appears to be a duplicate of an existing record or another entry in this file.
                </p>
                <div className="p-4 bg-orange-50 rounded-lg border border-orange-100 space-y-2">
                    <div className="flex justify-between">
                        <span className="text-sm font-medium text-orange-900">New Transaction</span>
                        <Badge variant="outline" className="bg-white text-orange-600 border-orange-200">
                            {transaction.duplicateReason}
                        </Badge>
                    </div>
                    <div className="grid grid-cols-2 gap-2 text-sm mt-2">
                        <div>
                            <span className="text-xs text-orange-700/70 block uppercase">Date</span>
                            <span className="font-medium text-orange-900">{transaction.date}</span>
                        </div>
                        <div className="text-right">
                             <span className="text-xs text-orange-700/70 block uppercase">Amount</span>
                             <span className="font-medium text-orange-900 font-mono">{formatCurrency(transaction.amount)}</span>
                        </div>
                        <div className="col-span-2">
                             <span className="text-xs text-orange-700/70 block uppercase">Description</span>
                             <span className="font-medium text-orange-900 truncate block">{transaction.description}</span>
                        </div>
                    </div>
                </div>
            </div>

            {exactMatches.length > 0 && (
                <div className="space-y-2">
                    <p className="text-xs font-semibold text-gray-500 uppercase tracking-wide">
                        Existing Match ({exactMatches.length})
                    </p>
                    {exactMatches.slice(0, 1).map(match => (
                        <div key={match.id} className="p-3 bg-gray-50 rounded border border-gray-200 opacity-75">
                             <div className="flex justify-between text-sm text-gray-700">
                                 <span>{match.date}</span>
                                 <span className="font-mono">{formatCurrency(match.amount)}</span>
                             </div>
                             <p className="text-xs text-gray-500 mt-1 truncate">{match.description}</p>
                        </div>
                    ))}
                </div>
            )}

            <div className="flex justify-end gap-3 pt-2">
                <Button variant="outline" onClick={onClose}>Discard</Button>
                <Button onClick={onImport} className="bg-orange-600 hover:bg-orange-700 text-white">
                    Import Anyway
                </Button>
            </div>
        </CardContent>
      </Card>
    </div>
  );
};

const ITEMS_PER_PAGE = 10;

// Helper to get transaction signature
const getTxSignature = (t: Transaction) => `${t.date}|${t.description}|${t.amount}`;

interface CSVUploaderProps {
  onUploadComplete?: () => void;
}

export const CSVUploader: React.FC<CSVUploaderProps> = ({ onUploadComplete }) => {
  const [state, setState] = useState<UploaderState>('idle');
  const [dragActive, setDragActive] = useState(false);
  const [file, setFile] = useState<File | null>(null);
  const [headers, setHeaders] = useState<string[]>([]);

  // Mapping State
  const [mapping, setMapping] = useState<CsvMapping>({ dateCol: '', descCol: '', amountCol: '', categoryCol: '', hasHeader: true, delimiter: ',' });
  const [mappingPreview, setMappingPreview] = useState<Transaction[]>([]);

  // Preview State
  const [stagedTransactions, setStagedTransactions] = useState<Transaction[]>([]);
  const [duplicateTransactions, setDuplicateTransactions] = useState<DuplicateTransaction[]>([]);
  const [activeTab, setActiveTab] = useState<PreviewTab>('new');
  const [currentPage, setCurrentPage] = useState(1);
  const [selectedDuplicate, setSelectedDuplicate] = useState<DuplicateTransaction | null>(null);

  const inputRef = useRef<HTMLInputElement>(null);
  const { addTransactions, transactions: existingTransactions, setError, error, clearAll } = useTransactionStore();
  const { applyPatterns: shouldApplyPatterns, isDemoMode, setDemoMode } = useSettingsStore();

  // Reset when component mounts or unmounts
  useEffect(() => {
    return () => {
        if (state !== 'idle') reset();
    };
  }, []);

  // Update preview when mapping changes
  useEffect(() => {
    if (state === 'mapping' && file) {
        getPreviewTransactions(file, mapping).then(setMappingPreview);
    }
  }, [mapping, state, file]);

  const reset = () => {
    setState('idle');
    setFile(null);
    setHeaders([]);
    setStagedTransactions([]);
    setDuplicateTransactions([]);
    setCurrentPage(1);
    setActiveTab('new');
    setSelectedDuplicate(null);
    setError(null);
    setMappingPreview([]);
  };

  const handleFileSelection = async (selectedFile: File) => {
    if (selectedFile.size > MAX_FILE_SIZE_MB * 1024 * 1024) {
      setError(`File size exceeds ${MAX_FILE_SIZE_MB}MB`);
      return;
    }

    setFile(selectedFile);
    setError(null);

    try {
        const { headers: extractedHeaders, delimiter } = await getCSVHeaders(selectedFile);
        setHeaders(extractedHeaders);

        // 1. Try Strict Bank Format
        const detected = detectBankFormat(extractedHeaders);
        if (detected) {
            const completeMapping: CsvMapping = {
                ...detected,
                hasHeader: true,
                delimiter: delimiter,
                dateCol: detected.dateCol || '',
                descCol: detected.descCol || '',
                amountCol: detected.amountCol || '',
                categoryCol: detected.categoryCol || '',
            };
            setMapping(completeMapping);
            await processFile(selectedFile, completeMapping);
            return;
        } 

        // 2. Try Smart Auto-Detection
        const autoMapping = autoDetectMapping(extractedHeaders, delimiter);

        // If we found at least a Date and Amount, we can try to proceed or just pre-fill the mapping screen
        if (autoMapping.dateCol && autoMapping.amountCol) {
             setMapping(autoMapping);
        } else {
             // Fallback default
             setMapping({
                dateCol: extractedHeaders[0] || '',
                descCol: extractedHeaders[1] || '',
                amountCol: extractedHeaders[2] || '',
                categoryCol: '',
                hasHeader: true,
                delimiter: delimiter
             });
        }

        // Go to mapping screen for user verification
        setState('mapping');

    } catch (e: any) {
        setError("Failed to read CSV. Check file format.");
        console.error(e);
        reset();
    }
  };

  const processFile = async (f: File, m: CsvMapping) => {
      setState('processing');
      try {
          let parsed = await parseCSVWithMapping(f, m);

          if (shouldApplyPatterns) {
              const result = applyPatterns(parsed);
              parsed = result.transactions;
          }

          // Deduplication Logic
          const existingSignatures = new Set(existingTransactions.map(getTxSignature));
          const newItems: Transaction[] = [];
          const duplicates: DuplicateTransaction[] = [];
          const currentBatchSignatures = new Set<string>();

          parsed.forEach(t => {
              const sig = getTxSignature(t);

              if (existingSignatures.has(sig)) {
                  duplicates.push({ ...t, duplicateReason: 'Already Imported' });
              } else if (currentBatchSignatures.has(sig)) {
                  duplicates.push({ ...t, duplicateReason: 'Duplicate in File' });
              } else {
                  newItems.push(t);
                  currentBatchSignatures.add(sig); 
              }
          });

          setStagedTransactions(newItems);
          setDuplicateTransactions(duplicates);
          setCurrentPage(1);
          // If no new items but duplicates exist, switch to duplicate tab automatically
          if (newItems.length === 0 && duplicates.length > 0) {
              setActiveTab('duplicates');
          } else {
              setActiveTab('new');
          }
          setState('preview');

      } catch (e: any) {
          setError(e.message);
          setState('idle');
      }
  };

  const removeStagedTransaction = (id: string) => {
      setStagedTransactions(prev => prev.filter(t => t.id !== id));
      // Adjust page if current page becomes empty
      const totalPages = Math.ceil((stagedTransactions.length - 1) / ITEMS_PER_PAGE);
      if (currentPage > totalPages && totalPages > 0) {
          setCurrentPage(totalPages);
      }
  };

  const restoreDuplicate = (tx: DuplicateTransaction) => {
      // Create a new transaction based on the duplicate, but with a new ID and modified description
      // We explicitly exclude duplicateReason from the new object
      const { duplicateReason, ...rawTx } = tx;

      const restoredTx: Transaction = {
          ...rawTx,
          id: uuidv4(),
          description: `${rawTx.description} (Copy)`
      };

      setStagedTransactions(prev => [...prev, restoredTx]);
      setDuplicateTransactions(prev => prev.filter(t => t.id !== tx.id));

      // If duplicates empty, switch view
      if (duplicateTransactions.length === 1) {
          setActiveTab('new');
      }
  };

  const handleDrag = (e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    if (e.type === 'dragenter' || e.type === 'dragover') setDragActive(true);
    else if (e.type === 'dragleave') setDragActive(false);
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    setDragActive(false);
    if (e.dataTransfer.files?.[0]) handleFileSelection(e.dataTransfer.files[0]);
  };

  const confirmImport = () => {
      // If user is importing data while in Demo Mode, assume they want to start fresh with real data.
      if (isDemoMode) {
          clearAll();
          setDemoMode(false);
      }

      addTransactions(stagedTransactions);
      reset();
      if (onUploadComplete) onUploadComplete();
  };

  // --- PAGINATION HELPERS ---
  const getCurrentPageData = (data: (Transaction | DuplicateTransaction)[]) => {
      const startIndex = (currentPage - 1) * ITEMS_PER_PAGE;
      return data.slice(startIndex, startIndex + ITEMS_PER_PAGE);
  };

  const totalPages = Math.ceil(
      (activeTab === 'new' ? stagedTransactions.length : duplicateTransactions.length) / ITEMS_PER_PAGE
  );

  // --- RENDERERS ---

  if (state === 'mapping') {
      return (
          <Card className="w-full max-w-2xl mx-auto mt-10">
              <CardHeader>
                  <CardTitle>Map Columns</CardTitle>
                  <p className="text-sm text-gray-500">We couldn't auto-detect your bank format. Please map the columns below.</p>
              </CardHeader>
              <CardContent className="space-y-6">
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                      <div className="space-y-2">
                          <label className="text-sm font-medium">Date Column</label>
                          <select 
                            className="w-full p-2 border rounded-md"
                            value={mapping.dateCol}
                            onChange={(e) => setMapping({...mapping, dateCol: e.target.value})}
                          >
                              {headers.map(h => <option key={h} value={h}>{h}</option>)}
                          </select>
                      </div>
                      <div className="space-y-2">
                          <label className="text-sm font-medium">Description</label>
                          <select 
                            className="w-full p-2 border rounded-md"
                            value={mapping.descCol}
                            onChange={(e) => setMapping({...mapping, descCol: e.target.value})}
                          >
                              {headers.map(h => <option key={h} value={h}>{h}</option>)}
                          </select>
                      </div>
                      <div className="space-y-2">
                          <label className="text-sm font-medium">Amount</label>
                          <select 
                            className="w-full p-2 border rounded-md"
                            value={mapping.amountCol}
                            onChange={(e) => setMapping({...mapping, amountCol: e.target.value})}
                          >
                              {headers.map(h => <option key={h} value={h}>{h}</option>)}
                          </select>
                      </div>
                      <div className="space-y-2">
                          <label className="text-sm font-medium flex items-center gap-1">
                            Category <span className="text-gray-400 font-normal">(Optional)</span>
                          </label>
                          <select 
                            className="w-full p-2 border rounded-md bg-gray-50"
                            value={mapping.categoryCol || ''}
                            onChange={(e) => setMapping({...mapping, categoryCol: e.target.value})}
                          >
                              <option value="">-- None --</option>
                              {headers.map(h => <option key={h} value={h}>{h}</option>)}
                          </select>
                      </div>
                  </div>

                  {/* Mapping Preview Table */}
                  <div className="rounded-lg border border-gray-200 overflow-hidden">
                      <div className="bg-gray-50 px-4 py-2 border-b border-gray-200 flex justify-between items-center">
                          <span className="text-xs font-semibold text-gray-500 uppercase tracking-wider">Preview</span>
                          <span className="text-xs text-gray-400">Showing first 10 rows based on current mapping</span>
                      </div>
                      <div className="overflow-x-auto max-h-60">
                          <table className="w-full text-sm text-left">
                              <thead className="bg-white text-gray-500 border-b border-gray-100 sticky top-0 shadow-sm z-10">
                                  <tr>
                                      <th className="px-4 py-2 font-medium bg-gray-50/50">Date</th>
                                      <th className="px-4 py-2 font-medium bg-gray-50/50">Description</th>
