  );
};

import { create } from 'zustand';
import { persist } from 'zustand/middleware';
import { AppSettings, AIMode, GeminiConfig, OllamaConfig, GroqConfig } from '../types';

interface SettingsState extends AppSettings {
  setAiMode: (mode: AIMode) => void;
  setDemoMode: (isDemo: boolean) => void;
  toggleApplyPatterns: () => void;
  toggleFunnyAlerts: () => void;
  setGeminiConfig: (config: Partial<GeminiConfig>) => void;
  setGroqConfig: (config: Partial<GroqConfig>) => void;
  setOllamaConfig: (config: Partial<OllamaConfig>) => void;
  resetSettings: () => void;
}

// Simple obfuscation to prevent plain-text read in local storage (not military grade encryption)
const encrypt = (text: string) => {
    try { return btoa(text); } catch(e) { return text; }
};
const decrypt = (text: string) => {
    try { return atob(text); } catch(e) { return text; }
};

// Detect Environment Keys for Gemini
export const getEnvGeminiApiKey = () => {
    try {
        // Check specific Google keys first, then generic
        return process.env.GOOGLE_API_KEY || process.env.GEMINI_API_KEY || process.env.API_KEY || '';
    } catch {
        return '';
    }
};

export const useSettingsStore = create<SettingsState>()(
  persist(
    (set) => ({
      aiMode: 'cloud',
      isDemoMode: false,
      applyPatterns: true,
      enableFunnyAlerts: true, // Default to true

      geminiConfig: {
        apiKey: encrypt(getEnvGeminiApiKey()),
        model: 'models/gemini-flash-latest'
      },

      groqConfig: {
        apiKey: '',
        model: 'llama-3.1-8b-instant'
      },

      ollamaConfig: {
        baseUrl: 'http://localhost',
        port: '11434',
        model: 'llama3.2'
      },

      setAiMode: (mode) => set({ aiMode: mode }),
      setDemoMode: (isDemo) => set({ isDemoMode: isDemo }),
      toggleApplyPatterns: () => set((state) => ({ applyPatterns: !state.applyPatterns })),
      toggleFunnyAlerts: () => set((state) => ({ enableFunnyAlerts: !state.enableFunnyAlerts })),

      setGeminiConfig: (config) => set((state) => {
          const newConfig = { ...state.geminiConfig, ...config };
          if (config.apiKey) {
              newConfig.apiKey = encrypt(config.apiKey);
          }
          return { geminiConfig: newConfig };
      }),

      setGroqConfig: (config) => set((state) => {
        const newConfig = { ...state.groqConfig, ...config };
        if (config.apiKey) {
            newConfig.apiKey = encrypt(config.apiKey);
        }
        return { groqConfig: newConfig };
      }),

      setOllamaConfig: (config) => set((state) => ({ 
          ollamaConfig: { ...state.ollamaConfig, ...config } 
      })),

      resetSettings: () => set({ 
          aiMode: 'cloud', 
          isDemoMode: false,
          applyPatterns: true,
          enableFunnyAlerts: true,
          geminiConfig: { apiKey: encrypt(getEnvGeminiApiKey()), model: 'models/gemini-flash-latest' },
          groqConfig: { apiKey: '', model: 'llama-3.1-8b-instant' },
          ollamaConfig: { baseUrl: 'http://localhost', port: '11434', model: 'llama3.2' }
      }),
    }),
    {
      name: 'moneymind-settings',
    }
  )
);

// Helper to get usable key based on active mode
export const getDecryptedApiKey = (storeState: SettingsState) => {
    if (storeState.aiMode === 'groq') {
        return decrypt(storeState.groqConfig.apiKey);
    }
    // Default to gemini for cloud mode
    return decrypt(storeState.geminiConfig.apiKey);
};

import React, { useState, useRef } from 'react';
import { useSettingsStore, getDecryptedApiKey, getEnvGeminiApiKey } from '../stores/useSettingsStore';
import { clearPatterns, getPatterns, importPatterns } from '../lib/localStorage';
import { Card, CardContent, CardHeader, CardTitle, Button, Input, Badge } from '../components/UI';
import { Trash2, CheckCircle, Circle, Cloud, Cpu, Terminal, Key, Server, PlayCircle, AlertCircle, Loader2, Zap, Download, Upload, MessageCircle, Info } from 'lucide-react';
import { testAiConnection } from '../services/aiService';
import { useToastStore } from '../stores/useToastStore';

export const SettingsPage: React.FC<{ onBack: () => void }> = ({ onBack }) => {
    const { 
        aiMode, setAiMode, 
        applyPatterns, toggleApplyPatterns,
        enableFunnyAlerts, toggleFunnyAlerts, 
        geminiConfig, setGeminiConfig,
        groqConfig, setGroqConfig,
        ollamaConfig, setOllamaConfig
    } = useSettingsStore();

    const { addToast } = useToastStore();

    const [isTesting, setIsTesting] = useState(false);
    const [testResult, setTestResult] = useState<'success' | 'error' | null>(null);
    const [testMessage, setTestMessage] = useState('');
    const [patternCount, setPatternCount] = useState(getPatterns().length);
    const fileInputRef = useRef<HTMLInputElement>(null);

    // Check for environment key presence for UI notification
    const envKeyDetected = !!getEnvGeminiApiKey();

    const handleClearPatterns = () => {
        // Removed confirm()
        clearPatterns();
        setPatternCount(0);
        addToast('Patterns cleared successfully', 'success');
    };

    const handleExportPatterns = () => {
        const patterns = getPatterns();
        const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify(patterns, null, 2));
        const downloadAnchorNode = document.createElement('a');
        downloadAnchorNode.setAttribute("href", dataStr);
        downloadAnchorNode.setAttribute("download", `moneymind_patterns_${new Date().toISOString().slice(0, 10)}.json`);
        document.body.appendChild(downloadAnchorNode);
        downloadAnchorNode.click();
        downloadAnchorNode.remove();
        addToast('Patterns exported', 'success');
    };

    const handleImportClick = () => {
        fileInputRef.current?.click();
    };

    const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (!file) return;

        const reader = new FileReader();
        reader.onload = (event) => {
            const content = event.target?.result as string;
            if (content) {
                const result = importPatterns(content);
                if (result.success) {
                    setPatternCount(getPatterns().length);
                    addToast(`Successfully imported ${result.count} patterns`, 'success');
                } else {
                    addToast(`Import failed: ${result.error}`, 'error');
                }
            }
        };
        reader.readAsText(file);
        // Reset input so same file can be selected again if needed
        e.target.value = ''; 
    };

    const handleTestConnection = async () => {
        setIsTesting(true);
        setTestResult(null);
        setTestMessage('');
        try {
            await testAiConnection();
            setTestResult('success');
            setTestMessage('Connection successful!');
        } catch (e: any) {
            setTestResult('error');
            setTestMessage(e.message);
        } finally {
            setIsTesting(false);
        }
