import React, { useState, useRef, useEffect } from 'react';
import { useTransactionStore } from '../stores/useTransactionStore';
import { useSettingsStore } from '../stores/useSettingsStore';
import { chatWithFinancialAgent } from '../services/aiService';
import { Transaction, TransactionCategory } from '../types';
import { MessageCircle, Send, X, Smile, Settings, Loader2 } from 'lucide-react';
import { Button, Input, Card, CardHeader, CardContent } from './UI';
import { cn, formatCurrency } from '../lib/utils';

interface Message {
    id: string;
    role: 'user' | 'assistant';
    content: string;
    timestamp: number;
}

interface MonkeySmileChatProps {
    onNavigate?: (view: 'settings' | 'dashboard' | 'upload') => void;
}

export const MonkeySmileChat: React.FC<MonkeySmileChatProps> = ({ onNavigate }) => {
    const { transactions } = useTransactionStore();
    // Subscribe to config objects so component re-renders when keys are updated
    const { isDemoMode, aiMode, geminiConfig, groqConfig } = useSettingsStore();
    const [isOpen, setIsOpen] = useState(false);
    const [messages, setMessages] = useState<Message[]>([
        { 
            id: 'intro', 
            role: 'assistant', 
            content: "Hey! I'm MonkeySmile 🐵. Ask me anything about your budget. Try 'Can I afford pizza?' or 'Roast my spending'.", 
            timestamp: Date.now() 
        }
    ]);
    const [inputValue, setInputValue] = useState('');
    const [isLoading, setIsLoading] = useState(false);
    const messagesEndRef = useRef<HTMLDivElement>(null);

    // Scroll to bottom
    useEffect(() => {
        if (messagesEndRef.current) {
            messagesEndRef.current.scrollIntoView({ behavior: 'smooth' });
        }
    }, [messages, isOpen]);

    const isAIReady = React.useMemo(() => {
        if (aiMode === 'local') return true;

        // If Cloud mode, we allow fallback to server proxy if no key is present
        if (aiMode === 'cloud') {
            return true; 
        }

        if (aiMode === 'groq') {
            return !!groqConfig.apiKey && groqConfig.apiKey.length > 0;
        }

        return false;
    }, [aiMode, geminiConfig.apiKey, groqConfig.apiKey]);

    const buildFinancialContext = (txs: Transaction[]) => {
        if (txs.length === 0) return "No transaction data available.";

        // Find the latest date in the dataset to determine the "Current Month" context
        // This ensures that if the data is from 2023, we analyze 2023, not today's empty month.
        const sortedTxs = [...txs].sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
        const latestDate = sortedTxs[0].date; 
        const currentMonthPrefix = latestDate.slice(0, 7); // YYYY-MM

        const monthlyTx = txs.filter(t => t.date.startsWith(currentMonthPrefix));

        const income = monthlyTx.filter(t => t.amount > 0).reduce((sum, t) => sum + t.amount, 0);
        const expenses = monthlyTx.filter(t => t.amount < 0).reduce((sum, t) => sum + Math.abs(t.amount), 0);
        const niceToHave = monthlyTx.filter(t => t.category === TransactionCategory.NiceToHave).reduce((sum, t) => sum + Math.abs(t.amount), 0);
        const waste = monthlyTx.filter(t => t.category === TransactionCategory.Waste).reduce((sum, t) => sum + Math.abs(t.amount), 0);

        // Group expenses by category
        const byCat: Record<string, number> = {};
        monthlyTx.filter(t => t.amount < 0).forEach(t => {
            byCat[t.category] = (byCat[t.category] || 0) + Math.abs(t.amount);
        });

        const topCategories = Object.entries(byCat)
            .sort(([,a], [,b]) => b - a)
            .slice(0, 3)
            .map(([cat, amt]) => `${cat}: ${formatCurrency(amt)}`)
            .join(', ');

        // Calculate All-Time stats for broader context
        const allTimeIncome = txs.filter(t => t.amount > 0).reduce((sum, t) => sum + t.amount, 0);
        const allTimeExpenses = txs.filter(t => t.amount < 0).reduce((sum, t) => sum + Math.abs(t.amount), 0);
        const netWorthProxy = allTimeIncome - allTimeExpenses; // Crude approximation within dataset

        return `
        CONTEXT PERIOD: ${currentMonthPrefix} (Most recent data available)

        MONTHLY SNAPSHOT (${currentMonthPrefix}):
        - Total Income: ${formatCurrency(income)}
        - Total Expenses: ${formatCurrency(expenses)}
        - Net Balance: ${formatCurrency(income - expenses)}
        - 'Nice-to-Have' Spend: ${formatCurrency(niceToHave)}
        - 'Waste' Spend: ${formatCurrency(waste)}
        - Top Categories: ${topCategories}
        - Transaction Count: ${monthlyTx.length}

        RECENT TRANSACTIONS (Last 5): 
        ${monthlyTx.slice(0, 5).map(t => `- ${t.date}: ${t.description} (${formatCurrency(t.amount)}) [${t.category}]`).join('\n')}

        ALL-TIME DATA (${txs.length} txs total):
        - Total Inflow: ${formatCurrency(allTimeIncome)}
        - Total Outflow: ${formatCurrency(allTimeExpenses)}
        - Calculated Net (Inflow - Outflow): ${formatCurrency(netWorthProxy)}
        `;
    };

    const handleSend = async (e?: React.FormEvent) => {
        e?.preventDefault();
        if (!inputValue.trim()) return;

        const userMsg: Message = {
            id: Date.now().toString(),
            role: 'user',
            content: inputValue.trim(),
            timestamp: Date.now()
        };

        setMessages(prev => [...prev, userMsg]);
        setInputValue('');
        setIsLoading(true);

        try {
            if (!isAIReady) {
                // Simulate delay then show error
                setTimeout(() => {
                    const errorMsg: Message = {
                        id: (Date.now() + 1).toString(),
                        role: 'assistant',
                        content: "I'd love to chat, but I need a brain! 🧠\n\nPlease go to Settings to configure your AI model.",
                        timestamp: Date.now()
                    };
                    setMessages(prev => [...prev, errorMsg]);
                    setIsLoading(false);
                }, 600);
                return;
            }

            const context = buildFinancialContext(transactions);
            const responseText = await chatWithFinancialAgent(userMsg.content, context);

            const botMsg: Message = {
                id: (Date.now() + 1).toString(),
                role: 'assistant',
                content: responseText,
                timestamp: Date.now()
            };
            setMessages(prev => [...prev, botMsg]);
        } catch (error: any) {
            // Handle Budget Error specifically
            const isBudgetError = error.message.includes("Budget Exceeded");
            const errorMsg: Message = {
                id: (Date.now() + 1).toString(),
                role: 'assistant',
                content: isBudgetError 
                    ? `🙊 Uh oh! ${error.message}\n\nGo to Settings to reset your usage limits.` 
                    : `Oops! Something went wrong: ${error.message}`,
                timestamp: Date.now()
            };
            setMessages(prev => [...prev, errorMsg]);
        } finally {
            setIsLoading(false);
        }
    };

    if (transactions.length === 0) return null;

    return (
        <>
            {/* Toggle Button */}
            <button
                onClick={() => setIsOpen(!isOpen)}
                className={cn(
                    "fixed bottom-6 right-6 z-40 p-4 rounded-full shadow-xl transition-all duration-300 hover:scale-105",
                    isOpen ? "bg-red-500 text-white rotate-90" : "bg-gradient-to-tr from-accent to-emerald-600 text-white"
                )}
                aria-label="Toggle MonkeySmile Chat"
            >
                {isOpen ? <X className="w-6 h-6" /> : <Smile className="w-6 h-6" />}
            </button>

            {/* Chat Window */}
            {isOpen && (
                <div className="fixed bottom-24 right-6 z-40 w-80 sm:w-96 flex flex-col animate-in slide-in-from-bottom-10 fade-in duration-300 origin-bottom-right">
                    <Card className="shadow-2xl border-0 overflow-hidden flex flex-col h-[500px]">
                        {/* Header */}
                        <div className="bg-gradient-to-r from-accent to-emerald-600 p-4 flex justify-between items-center text-white shrink-0">
                            <div className="flex items-center gap-2">
                                <div className="bg-white/20 p-1.5 rounded-full backdrop-blur-sm">
                                    <Smile className="w-5 h-5" />
                                </div>
                                <div>
                                    <h3 className="font-bold text-sm">MonkeySmile 🐵</h3>
                                    <p className="text-[10px] text-white/80 font-medium">Your Sassy Budget Buddy</p>
                                </div>
                            </div>
                            {/* If we have demo data AND no AI key, show DEMO. If we have AI key, we are 'Live' even with demo data. */}
                            {!isAIReady && isDemoMode && (
                                <div className="bg-white/20 px-2 py-0.5 rounded text-[10px] font-bold border border-white/10">
                                    DEMO
                                </div>
                            )}
                        </div>

                        {/* Messages */}
                        <div className="flex-1 overflow-y-auto p-4 space-y-4 bg-gray-50/50">
                            {messages.map((msg) => (
                                <div
                                    key={msg.id}
                                    className={cn(
                                        "flex w-full",
                                        msg.role === 'user' ? "justify-end" : "justify-start"
                                    )}
                                >
                                    <div
                                        className={cn(
                                            "max-w-[80%] rounded-2xl px-4 py-2.5 text-sm shadow-sm whitespace-pre-wrap",
                                            msg.role === 'user' 
                                                ? "bg-accent text-white rounded-br-none" 
                                                : "bg-white text-gray-800 border border-gray-100 rounded-bl-none"
                                        )}
                                    >
                                        {msg.content}
                                    </div>
                                </div>
                            ))}
                            {isLoading && (
                                <div className="flex justify-start w-full">
                                    <div className="bg-white border border-gray-100 px-4 py-3 rounded-2xl rounded-bl-none shadow-sm flex items-center gap-2">
                                        <div className="w-2 h-2 bg-gray-400 rounded-full animate-bounce [animation-delay:-0.3s]"></div>
                                        <div className="w-2 h-2 bg-gray-400 rounded-full animate-bounce [animation-delay:-0.15s]"></div>
                                        <div className="w-2 h-2 bg-gray-400 rounded-full animate-bounce"></div>
                                    </div>
                                </div>
                            )}
                            <div ref={messagesEndRef} />
                        </div>

                        {/* Footer / Input */}
                        <div className="p-3 bg-white border-t border-gray-100 shrink-0">
                            {!isAIReady ? (
                                <div className="text-center p-2 space-y-2">
                                    <p className="text-xs text-gray-500">
                                        Connect AI to chat with your data.
                                    </p>
                                    <Button size="sm" variant="outline" className="w-full text-xs" onClick={() => {
                                        if (onNavigate) {
                                            setIsOpen(false);
                                            onNavigate('settings');
                                        }
                                    }}>
                                        <Settings className="w-3 h-3 mr-1.5" />
                                        Configure in Settings
                                    </Button>
                                </div>
                            ) : null}

                            <form 
                                onSubmit={handleSend}
                                className={cn("flex items-center gap-2", !isAIReady && "opacity-50 pointer-events-none")}
                            >
                                <Input
                                    value={inputValue}
                                    onChange={(e) => setInputValue(e.target.value)}
                                    placeholder="Type a message..."
                                    className="flex-1 text-sm bg-gray-50 border-0 focus-visible:ring-1 focus-visible:ring-accent focus-visible:bg-white transition-all"
                                />
                                <Button 
                                    type="submit" 
                                    size="sm" 
                                    className="px-3 bg-accent hover:bg-accent-hover text-white shadow-sm"
                                    disabled={!inputValue.trim() || isLoading}
                                >
                                    <Send className="w-4 h-4" />
                                </Button>
                            </form>
                        </div>
                    </Card>
                </div>
            )}
        </>
    );
};

import React, { useMemo, useState, useEffect } from 'react';
import { useTransactionStore } from '../stores/useTransactionStore';
import { useSettingsStore, getDecryptedApiKey } from '../stores/useSettingsStore';
import { getPatterns, learnPattern } from '../lib/localStorage';
import { TransactionTable } from '../components/TransactionTable';
import { InsightsDashboard, MonthlyPerformance } from '../components/InsightsDashboard';
import { FinancialScoreCard } from '../components/FinancialScoreCard';
import { categorizeWithAI } from '../services/aiService';
import { checkFinancialHealth } from '../services/alertService';
import { useToastStore, ToastType } from '../stores/useToastStore';
import { Button, Card, CardContent } from '../components/UI';
import { AddTransactionModal } from '../components/AddTransactionModal';
import { Zap, AlertOctagon, Loader2, Settings, Calendar, RefreshCw, X, Activity, CheckCircle2, AlertTriangle, ArrowRightLeft, BookOpen, RotateCcw, Plus, LayoutDashboard, List } from 'lucide-react';
import { TransactionCategory, Transaction } from '../types';
import { cn } from '../lib/utils';

interface DashboardProps {
    onNavigate: (view: 'settings' | 'upload' | 'dashboard') => void;
}

interface AnalysisStats {
    total: number;
    changed: number;
    highConfidence: number;
    mediumConfidence: number;
    lowConfidence: number;
    duration: number;
}

type TimeRange = 'week' | 'month' | 'all';
type TabView = 'insights' | 'transactions';

export const Dashboard: React.FC<DashboardProps> = ({ onNavigate }) => {
    const { 
        transactions, 
        setCategorizing, 
        isCategorizing, 
        updateTransactionBatch, 
        addTransactions,
        applyLocalPatterns,
        setError,
        error,
        processedCount,
        totalToProcess,
        setProgressCounts
    } = useTransactionStore();

    const { aiMode, geminiConfig, isDemoMode, enableFunnyAlerts } = useSettingsStore();
    const { addToast } = useToastStore();

    // Time Filter & Tab State
    const [timeRange, setTimeRange] = useState<TimeRange>('all');
    const [activeTab, setActiveTab] = useState<TabView>('insights');
    const [analysisStats, setAnalysisStats] = useState<AnalysisStats | null>(null);
    const [isAddModalOpen, setIsAddModalOpen] = useState(false);

    // Run Alert Check on Mount or when transactions change significantly
    useEffect(() => {
        if (enableFunnyAlerts && transactions.length > 0 && !isCategorizing) {
            // Delay slightly to allow UI to settle
            const timer = setTimeout(() => {
                const alerts = checkFinancialHealth(transactions);
                alerts.forEach(alert => {
                    // Use the type provided by the alert service (warning/info)
                    // Ensure it matches ToastType (casted for safety)
                    addToast(alert.message, alert.type as ToastType, 6000); 
                });
            }, 1000);
            return () => clearTimeout(timer);
        }
    }, [transactions.length, isCategorizing, enableFunnyAlerts]);

    // Check if AI is configured or in demo mode
    const isAIConfigured = useMemo(() => {
        if (isDemoMode) return true;
        if (aiMode === 'local') return true; // Assume local is always "ready" to try
        const key = getDecryptedApiKey(useSettingsStore.getState());
        return !!key && key.length > 0;
    }, [aiMode, geminiConfig, isDemoMode]);

    // Check if we have local patterns
    const hasPatterns = useMemo(() => {
        return getPatterns().length > 0;
    }, [transactions]); // Re-check when transactions change (implies potential learning)

    // Filter Logic
    const displayedTransactions = useMemo(() => {
        if (timeRange === 'all') return transactions;
        if (transactions.length === 0) return [];

        const getTimestamp = (d: string) => {
            const date = new Date(d);
            return isNaN(date.getTime()) ? 0 : date.getTime();
        };

        const timestamps = transactions.map(t => getTimestamp(t.date)).filter(t => t > 0);
        if (timestamps.length === 0) return transactions;

        const maxDate = Math.max(...timestamps);
        const msPerDay = 1000 * 60 * 60 * 24;

        let daysToSubtract = 0;
        if (timeRange === 'week') daysToSubtract = 7;
        if (timeRange === 'month') daysToSubtract = 30;

        const cutoff = maxDate - (daysToSubtract * msPerDay);

        return transactions.filter(t => getTimestamp(t.date) >= cutoff);
    }, [transactions, timeRange]);

    // Calculate Date Range String
    const dateRangeDisplay = useMemo(() => {
        if (displayedTransactions.length === 0) return '';

        const timestamps = displayedTransactions
            .map(t => new Date(t.date).getTime())
            .filter(t => !isNaN(t));

        if (timestamps.length === 0) return '';

        const min = Math.min(...timestamps);
        const max = Math.max(...timestamps);

        const format = (ts: number) => new Intl.DateTimeFormat('en-US', { 
            month: 'short', 
            day: 'numeric', 
            year: 'numeric' 
        }).format(new Date(ts));

        if (min === max) return format(min);
        return `${format(min)} - ${format(max)}`;
    }, [displayedTransactions]);

    const performAIAnalysis = async (transactionsToProcess: any[]) => {
         setCategorizing(true);
         setAnalysisStats(null);
         setError(null); // Clear previous errors
         setProgressCounts(0, transactionsToProcess.length);
         const startTime = Date.now();
         let changesDetected = 0;

         try {
             await categorizeWithAI(transactionsToProcess, aiMode, (results) => {
                 // 1. Calculate changes before updating
                 const currentStore = useTransactionStore.getState().transactions;

                 results.forEach(res => {
                     const original = currentStore.find(t => t.id === res.id);
                     if (original) {
                         // Check if category or subcategory actually changed
                         if (original.category !== res.category || original.subCategory !== res.subCategory) {
                             changesDetected++;
                         }
                     }
                 });

                 // 2. Prepare updates
                 const updates = results.map(res => {
                     const original = transactions.find(t => t.id === res.id);
                     if (!original) return null;
                     return { 
                         ...original, 
                         category: res.category,
                         subCategory: res.subCategory, // Ensure subCategory is passed
                         confidence: res.confidence, 
                         reason: res.reason 
                     };
                 }).filter(Boolean) as any[];

                 // 3. Commit updates
                 updateTransactionBatch(updates);
                 const currentProcessed = useTransactionStore.getState().processedCount;
                 setProgressCounts(currentProcessed + results.length, transactionsToProcess.length);
             });

             // Calculate final stats after completion
             const duration = (Date.now() - startTime) / 1000;
             const currentTransactions = useTransactionStore.getState().transactions;
             const processedIds = new Set(transactionsToProcess.map(t => t.id));

             // Get the updated versions of the processed transactions
             const processed = currentTransactions.filter(t => processedIds.has(t.id));

             if (processed.length > 0) {
                 setAnalysisStats({
                     total: processed.length,
                     changed: changesDetected,
                     highConfidence: processed.filter(t => t.confidence >= 0.8).length,
                     mediumConfidence: processed.filter(t => t.confidence >= 0.5 && t.confidence < 0.8).length,
                     lowConfidence: processed.filter(t => t.confidence < 0.5).length,
                     duration
                 });
             }

         } catch (e: any) {
             setError(e.message);
         } finally {
             setCategorizing(false);
             setProgressCounts(0, 0);
         }
    };

    const handleInitialCategorize = async () => {
        if (!isAIConfigured) {
            onNavigate('settings');
            return;
        }

        const toProcess = transactions.filter(t => t.category === TransactionCategory.Uncategorized);
        if (toProcess.length === 0) return;

        await performAIAnalysis(toProcess);
    };

    const handleReanalyzeAll = async () => {
        if (!isAIConfigured) {
            onNavigate('settings');
            return;
        }

        // Re-analyze everything that is NOT explicitly approved
        const toProcess = transactions.filter(t => !t.isApproved);
        if (toProcess.length === 0) {
            return;
        }

        await performAIAnalysis(toProcess);
    };

    const handleRetryFailed = async () => {
        if (!isAIConfigured) {
            onNavigate('settings');
            return;
        }

        // Retry transactions that have an explicit error or are uncategorized with an error reason
        const toProcess = transactions.filter(t => t.reason?.includes('Failed') || t.reason?.includes('Error'));
        if (toProcess.length === 0) return;

        await performAIAnalysis(toProcess);
    }

    const handleApplyRules = () => {
        const count = applyLocalPatterns();
        setAnalysisStats({
            total: transactions.length, // Context: scanned all transactions
            changed: count,
            highConfidence: count, // Patterns represent high confidence
            mediumConfidence: 0,
            lowConfidence: 0,
            duration: 0.1
        });
